#!/bin/bash
# Uninstall script for R
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling R..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping R if running..."
pkill -f "R" 2>/dev/null || true

# Remove $HOME/.R
echo "Removing $HOME/.R..."
if [ -d "$HOME/.R" ]; then
    rm -rf "$HOME/.R" 2>/dev/null || true
elif [ -f "$HOME/.R" ]; then
    rm -f "$HOME/.R" 2>/dev/null || true
fi

# Remove $HOME/.Rapp.history
echo "Removing $HOME/.Rapp.history..."
if [ -d "$HOME/.Rapp.history" ]; then
    rm -rf "$HOME/.Rapp.history" 2>/dev/null || true
elif [ -f "$HOME/.Rapp.history" ]; then
    rm -f "$HOME/.Rapp.history" 2>/dev/null || true
fi

# Remove $HOME/.RData
echo "Removing $HOME/.RData..."
if [ -d "$HOME/.RData" ]; then
    rm -rf "$HOME/.RData" 2>/dev/null || true
elif [ -f "$HOME/.RData" ]; then
    rm -f "$HOME/.RData" 2>/dev/null || true
fi

# Remove $HOME/.Rhistory
echo "Removing $HOME/.Rhistory..."
if [ -d "$HOME/.Rhistory" ]; then
    rm -rf "$HOME/.Rhistory" 2>/dev/null || true
elif [ -f "$HOME/.Rhistory" ]; then
    rm -f "$HOME/.Rhistory" 2>/dev/null || true
fi

# Remove $HOME/.Rprofile
echo "Removing $HOME/.Rprofile..."
if [ -d "$HOME/.Rprofile" ]; then
    rm -rf "$HOME/.Rprofile" 2>/dev/null || true
elif [ -f "$HOME/.Rprofile" ]; then
    rm -f "$HOME/.Rprofile" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/org.R-project.R
echo "Removing $HOME/Library/Caches/org.R-project.R..."
if [ -d "$HOME/Library/Caches/org.R-project.R" ]; then
    rm -rf "$HOME/Library/Caches/org.R-project.R" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/org.R-project.R" ]; then
    rm -f "$HOME/Library/Caches/org.R-project.R" 2>/dev/null || true
fi

# Remove $HOME/Library/R
echo "Removing $HOME/Library/R..."
if [ -d "$HOME/Library/R" ]; then
    rm -rf "$HOME/Library/R" 2>/dev/null || true
elif [ -f "$HOME/Library/R" ]; then
    rm -f "$HOME/Library/R" 2>/dev/null || true
fi

# Remove /Library/Frameworks/R.Framework
echo "Removing /Library/Frameworks/R.Framework..."
if [ -d "/Library/Frameworks/R.Framework" ]; then
    rm -rf "/Library/Frameworks/R.Framework" 2>/dev/null || true
elif [ -f "/Library/Frameworks/R.Framework" ]; then
    rm -f "/Library/Frameworks/R.Framework" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
